c7baae7 Fix a buffer overflow (#311)
 src/spss/readstat_sav_read.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)
commit c7baae72b36acdc24f56ad48d3e859850fdbdc2b
Author: Gábor Csárdi <csardi.gabor@gmail.com>
Date:   Sat Feb 17 21:23:14 2024 +0100

    Fix a buffer overflow (#311)

    It happens if raw_str_used underflows and ends up a very large number,
    which is then used as the size of a string.

    Closes #285.

diff --git a/src/spss/readstat_sav_read.c b/src/spss/readstat_sav_read.c
index 7f49490..460bf07 100644
--- a/src/spss/readstat_sav_read.c
+++ b/src/spss/readstat_sav_read.c
@@ -717,7 +717,7 @@ static readstat_error_t sav_process_row(unsigned char *buffer, size_t buffer_len
             }
             if (++offset == col_info->width) {
                 if (++segment_offset < var_info->n_segments) {
-                    raw_str_used--;
+                    if (raw_str_used > 0) raw_str_used--;
                 }
                 offset = 0;
                 col++;
887d3a1 (origin/dev, origin/HEAD) [SAV reader] force parse error if attempting to decrement zero
 src/spss/readstat_sav_read.c | 6 +++++-
 1 file changed, 5 insertions(+), 1 deletion(-)
commit 887d3a1bbcf79c692923d98f8b584b32a50daebd
Author: Evan Miller <emmiller@gmail.com>
Date:   Sun Feb 18 14:44:23 2024 -0500

    [SAV reader] force parse error if attempting to decrement zero

diff --git a/src/spss/readstat_sav_read.c b/src/spss/readstat_sav_read.c
index 460bf07..d36bab9 100644
--- a/src/spss/readstat_sav_read.c
+++ b/src/spss/readstat_sav_read.c
@@ -717,7 +717,11 @@ static readstat_error_t sav_process_row(unsigned char *buffer, size_t buffer_len
             }
             if (++offset == col_info->width) {
                 if (++segment_offset < var_info->n_segments) {
-                    if (raw_str_used > 0) raw_str_used--;
+                    if (raw_str_used == 0) {
+                        retval = READSTAT_ERROR_PARSE;
+                        goto done;
+                    }
+                    raw_str_used--;
                 }
                 offset = 0;
                 col++;
